`timescale 1ns/1ps

// End-to-end attack-scenario regression for the integrated data plane.
//
// For every scenario generated by tools/generate_system_vectors.py the bench
// resets the core, loads the CRC-protected model over APB, arms the motor and
// streams accelerometer samples. It checks every anomaly score bit-exactly,
// the accepted-sample index at which the motor is disabled, the latched fault
// vector, the integrity cause register and the final motor state.
module tb_motorsentinel_core;

    localparam logic [7:0] REG_CONTROL          = 8'h04;
    localparam logic [7:0] REG_STATUS           = 8'h08;
    localparam logic [7:0] REG_IRQ_ENABLE       = 8'h10;
    localparam logic [7:0] REG_ANOM_THRESHOLD   = 8'h1c;
    localparam logic [7:0] REG_POLICY_CFG       = 8'h20;
    localparam logic [7:0] REG_ANOM_SCORE       = 8'h34;
    localparam logic [7:0] REG_FAULT_VECTOR     = 8'h38;
    localparam logic [7:0] REG_CORE_ID          = 8'h40;
    localparam logic [7:0] REG_CORE_CONTROL     = 8'h44;
    localparam logic [7:0] REG_INJECT_XY        = 8'h48;
    localparam logic [7:0] REG_INJECT_Z         = 8'h4c;
    localparam logic [7:0] REG_MODEL_CMD        = 8'h50;
    localparam logic [7:0] REG_MODEL_DATA       = 8'h54;
    localparam logic [7:0] REG_MODEL_CRC        = 8'h58;
    localparam logic [7:0] REG_MODEL_STATUS     = 8'h5c;
    localparam logic [7:0] REG_INTEGRITY_LIMITS = 8'h64;
    localparam logic [7:0] REG_INTEGRITY_CFG    = 8'h68;
    localparam logic [7:0] REG_INTEGRITY_STATUS = 8'h6c;
    localparam logic [7:0] REG_WINDOW_COUNT     = 8'h70;
    localparam logic [7:0] REG_LAST_SEQUENCE    = 8'h74;
    localparam logic [7:0] REG_LATENCY          = 8'h78;
    localparam logic [7:0] REG_INFERENCE_STATUS = 8'h7c;
    localparam logic [7:0] REG_FEATURE_BASE     = 8'h80;

    localparam integer IMAGE_WORDS = 122;
    localparam integer MANIFEST_WORDS = 10;
    localparam integer MAX_SCENARIOS = 9;
    localparam integer MAX_SAMPLES = MAX_SCENARIOS * 2816;
    localparam integer MAX_SCORES = MAX_SCENARIOS * 21;
    localparam logic [31:0] NONE = 32'hffff_ffff;

    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        psel = 1'b0;
    logic        penable = 1'b0;
    logic        pwrite = 1'b0;
    logic [7:0]  paddr = '0;
    logic [31:0] pwdata = '0;
    logic [31:0] prdata;
    logic        pready;
    logic        pslverr;

    logic        sample_nack = 1'b0;
    logic        sample_valid = 1'b0;
    logic        sample_ready;
    logic signed [15:0] sample_x = '0;
    logic signed [15:0] sample_y = '0;
    logic signed [15:0] sample_z = '0;
    logic        motor_enable;
    logic        fault_led;
    logic        irq;

    always #10 clk = ~clk;  // 50 MHz

    motorsentinel_core_apb dut (
        .PCLK                (clk),
        .PRESETn             (rst_n),
        .PSEL                (psel),
        .PENABLE             (penable),
        .PWRITE              (pwrite),
        .PADDR               (paddr),
        .PWDATA              (pwdata),
        .PRDATA              (prdata),
        .PREADY              (pready),
        .PSLVERR             (pslverr),
        .scl_i               (1'b1),
        .sda_i               (1'b1),
        .i2c_master_active_i (1'b0),
        .i2c_scl_release_i   (1'b0),
        .sample_nack_i       (sample_nack),
        .sample_valid_i      (sample_valid),
        .sample_ready_o      (sample_ready),
        .sample_x_i          (sample_x),
        .sample_y_i          (sample_y),
        .sample_z_i          (sample_z),
        .motor_enable_o      (motor_enable),
        .fault_led_o         (fault_led),
        .irq_o               (irq)
    );

    logic [31:0] image    [0:IMAGE_WORDS-1];
    logic [31:0] config_w [0:5];
    logic [31:0] manifest [0:MAX_SCENARIOS*MANIFEST_WORDS-1];
    logic [47:0] samples  [0:MAX_SAMPLES-1];
    logic [31:0] scores   [0:MAX_SCORES-1];

    integer checks = 0;
    integer failures = 0;
    integer scenario_count;
    integer s;
    integer n;
    integer w;
    integer sample_base = 0;
    integer score_base = 0;
    integer score_index;
    integer window_max_score;
    integer trip_sample;
    integer worst_latency = 0;
    integer detection_x100;
    logic [31:0] readback;
    logic [63:0] scenario_name;
    logic        streaming = 1'b0;

    task automatic check(input logic condition, input string message);
        begin
            checks = checks + 1;
            if (!condition) begin
                failures = failures + 1;
                $display("FAIL: %s (t=%0t)", message, $time);
            end
        end
    endtask

    task automatic apb_write(input logic [7:0] address, input logic [31:0] data);
        begin
            @(negedge clk);
            psel = 1'b1;
            penable = 1'b0;
            pwrite = 1'b1;
            paddr = address;
            pwdata = data;
            @(negedge clk);
            penable = 1'b1;
            @(negedge clk);
            psel = 1'b0;
            penable = 1'b0;
            pwrite = 1'b0;
        end
    endtask

    task automatic apb_read(input logic [7:0] address, output logic [31:0] data);
        begin
            @(negedge clk);
            psel = 1'b1;
            penable = 1'b0;
            pwrite = 1'b0;
            paddr = address;
            @(negedge clk);
            penable = 1'b1;
            #1 data = prdata;
            @(negedge clk);
            psel = 1'b0;
            penable = 1'b0;
        end
    endtask

    task automatic reset_core;
        begin
            @(negedge clk);
            rst_n = 1'b0;
            repeat (3) @(negedge clk);
            rst_n = 1'b1;
            repeat (2) @(negedge clk);
        end
    endtask

    task automatic load_model;
        integer word;
        begin
            apb_write(REG_MODEL_CMD, 32'h1);
            for (word = 0; word < IMAGE_WORDS; word = word + 1)
                apb_write(REG_MODEL_DATA, image[word]);
            apb_write(REG_MODEL_CRC, config_w[0]);
            apb_write(REG_MODEL_CMD, 32'h2);
            apb_read(REG_MODEL_STATUS, readback);
            check(readback[0] && readback[12:8] == 0 && readback[23:16] == IMAGE_WORDS,
                  "model image commits through APB with hardware CRC match");
        end
    endtask

    task automatic configure_and_arm;
        begin
            apb_write(REG_IRQ_ENABLE, 32'h0000_000f);
            apb_write(REG_ANOM_THRESHOLD, config_w[1]);
            apb_write(REG_POLICY_CFG, 32'h0003_0400 | config_w[5]);
            apb_write(REG_INTEGRITY_LIMITS, config_w[2]);
            apb_write(REG_INTEGRITY_CFG, config_w[3]);
            apb_write(REG_CONTROL, 32'h0000_0005);  // enable + arm
            repeat (2) @(negedge clk);
            check(motor_enable && !fault_led, "valid model arms the motor");
        end
    endtask

    // Wait until the previous sample has fully propagated, including any
    // window decision it closed, so trip timing is exact in sample units.
    task automatic wait_for_datapath;
        begin
            // Let integrity events reach the policy before the next sample.
            repeat (4) @(negedge clk);
            while (!(sample_ready && !dut.latency_running_q))
                @(negedge clk);
        end
    endtask

    task automatic push_sample(input logic [47:0] value);
        begin
            wait_for_datapath();
            sample_x = value[47:32];
            sample_y = value[31:16];
            sample_z = value[15:0];
            sample_valid = 1'b1;
            @(negedge clk);
            sample_valid = 1'b0;
        end
    endtask

    // Safety invariant checked every cycle for the whole regression.
    always @(negedge clk) begin
        if (rst_n && fault_led && motor_enable && !dut.u_guard.monitor_only_q)
            $fatal(1, "safety invariant failed: trip did not disable motor");
        if (rst_n && !dut.model_valid && motor_enable)
            $fatal(1, "safety invariant failed: motor enabled without a valid model");
    end

    // Record the accepted-sample count at which the motor is first disabled.
    always @(negedge clk) begin
        if (streaming && fault_led && trip_sample == NONE)
            trip_sample = dut.accepted_samples_q;
    end

    // Check every window decision against the Python reference.
    always @(negedge clk) begin
        if (streaming && dut.window_done) begin
            check(dut.score == scores[score_base + score_index][11:0],
                  "window anomaly score matches Python bit-exactly");
            if (dut.score != scores[score_base + score_index][11:0])
                $display("  window %0d: rtl=%0d expected=%0d", score_index,
                         dut.score, scores[score_base + score_index]);
            if (dut.score > window_max_score)
                window_max_score = dut.score;
            score_index = score_index + 1;
        end
    end

    initial begin
`ifdef DUMP_WAVES
        $dumpfile("build/motorsentinel_core.vcd");
        $dumpvars(0, tb_motorsentinel_core);
`endif
        $readmemh("build/model_image.hex", image);
        $readmemh("build/system_config.hex", config_w);
        $readmemh("build/system_manifest.hex", manifest);
        $readmemh("build/system_samples.hex", samples);
        $readmemh("build/system_scores.hex", scores);
        scenario_count = config_w[4];

        reset_core();
        apb_read(REG_CORE_ID, readback);
        check(readback == 32'h4d53_0300, "data-plane ID register");
        apb_read(8'h00, readback);
        check(readback == 32'h4d53_0100, "safety-kernel ID register is unchanged");

        $display("");
        $display("Scenario   Windows  MaxScore  TripSample  Detect(ms)  Faults  Integrity  Motor  Result");
        $display("---------  -------  --------  ----------  ----------  ------  ---------  -----  ------");

        for (s = 0; s < scenario_count; s = s + 1) begin
            scenario_name = {manifest[s*MANIFEST_WORDS], manifest[s*MANIFEST_WORDS+1]};
            reset_core();
            load_model();
            configure_and_arm();

            score_index = 0;
            window_max_score = 0;
            trip_sample = NONE;
            streaming = 1'b1;
            for (n = 0; n < manifest[s*MANIFEST_WORDS+2]; n = n + 1) begin
                push_sample(samples[sample_base + n]);
                if (n + 1 == manifest[s*MANIFEST_WORDS+4]) begin
                    // NACK storm: three failed transactions at this point.
                    wait_for_datapath();
                    repeat (3) begin
                        @(negedge clk);
                        sample_nack = 1'b1;
                        @(negedge clk);
                        sample_nack = 1'b0;
                    end
                    repeat (4) @(negedge clk);
                end
            end
            wait_for_datapath();
            repeat (8) @(negedge clk);
            streaming = 1'b0;

            check(score_index == manifest[s*MANIFEST_WORDS+5], "every window produced a decision");
            check(trip_sample == manifest[s*MANIFEST_WORDS+6], "motor disabled at the expected sample");
            apb_read(REG_FAULT_VECTOR, readback);
            check(readback[15:0] == manifest[s*MANIFEST_WORDS+7][15:0], "latched fault vector");
            apb_read(REG_INTEGRITY_STATUS, readback);
            check(readback[4:0] == manifest[s*MANIFEST_WORDS+8][4:0], "integrity cause register");
            check(motor_enable == manifest[s*MANIFEST_WORDS+9][0], "final motor state");
            apb_read(REG_WINDOW_COUNT, readback);
            check(readback == manifest[s*MANIFEST_WORDS+5], "window counter");
            apb_read(REG_LATENCY, readback);
            if (readback[31:16] > worst_latency)
                worst_latency = readback[31:16];

            // 800 samples/s: one sample is 1.25 ms.
            if (trip_sample != NONE && manifest[s*MANIFEST_WORDS+3] != NONE)
                detection_x100 = (trip_sample - manifest[s*MANIFEST_WORDS+3]) * 125;
            else
                detection_x100 = -1;
            apb_read(REG_FAULT_VECTOR, readback);
            if (detection_x100 >= 0)
                $display("%s   %7d  %8d  %10d  %7d.%02d   0x%03h  0x%01h        %s    %s",
                         scenario_name, score_index, window_max_score, trip_sample,
                         detection_x100 / 100, detection_x100 % 100, readback[11:0],
                         manifest[s*MANIFEST_WORDS+8][3:0], motor_enable ? "ON " : "OFF",
                         failures == 0 ? "PASS" : "FAIL");
            else
                $display("%s   %7d  %8d  %10s  %10s   0x%03h  0x%01h        %s    %s",
                         scenario_name, score_index, window_max_score, "none", "-",
                         readback[11:0], manifest[s*MANIFEST_WORDS+8][3:0],
                         motor_enable ? "ON " : "OFF", failures == 0 ? "PASS" : "FAIL");

            sample_base = sample_base + manifest[s*MANIFEST_WORDS+2];
            score_base = score_base + manifest[s*MANIFEST_WORDS+5];
            if (failures != 0)
                $fatal(1, "FAIL: scenario %0d", s);
        end

        // Directed: Linux can replay recorded data through APB injection and
        // obtain the identical hardware decision (hardware-in-the-loop mode).
        reset_core();
        load_model();
        configure_and_arm();
        apb_write(REG_CORE_CONTROL, 32'h1);
        // Software waits for the replay-table clear sweep after enable.
        readback = 0;
        while (!readback[20])
            apb_read(REG_INFERENCE_STATUS, readback);
        for (n = 0; n < 256; n = n + 1) begin
            apb_write(REG_INJECT_XY, {samples[n][31:16], samples[n][47:32]});
            apb_write(REG_INJECT_Z, {16'd0, samples[n][15:0]});
        end
        wait (!dut.latency_running_q);
        repeat (4) @(negedge clk);
        apb_read(REG_WINDOW_COUNT, readback);
        check(readback == 1, "APB-injected samples produce one window");
        apb_read(REG_ANOM_SCORE, readback);
        check(readback == scores[0], "APB-injected window score matches streamed result");
        apb_read(REG_LAST_SEQUENCE, readback);
        check(readback == 0, "window sequence is published");
        apb_read(REG_FEATURE_BASE + 8'h08, readback);
        check(readback == dut.window_features[2*32 +: 32], "feature snapshot is APB-readable");
        if (failures == 0)
            $display("PASS: APB sample injection reproduces the streamed decision (score %0d)",
                     scores[0]);

        // Directed: a sample offered while the window post-pass holds the
        // pipeline is dropped and must fail safe as an internal overrun.
        // Sample 384 closes the next window; sample 385 arrives inside its
        // 257-cycle zero-crossing post-pass.
        check(!fault_led, "no overrun while software respects the sample rate");
        for (n = 256; n < 385; n = n + 1) begin
            apb_write(REG_INJECT_XY, {samples[n][31:16], samples[n][47:32]});
            apb_write(REG_INJECT_Z, {16'd0, samples[n][15:0]});
        end
        repeat (4) @(negedge clk);
        apb_read(REG_INTEGRITY_STATUS, readback);
        check(readback[4], "dropped sample is recorded as an overrun");
        apb_read(REG_FAULT_VECTOR, readback);
        check(readback[7] && fault_led && !motor_enable,
              "overrun trips the internal-fault path and disables the motor");
        if (failures == 0)
            $display("PASS: sample overrun fails safe through the internal-fault path");

        if (failures == 0) begin
            $display("");
            $display("PASS: %0d end-to-end scenarios, %0d checks; worst sample-to-decision latency %0d cycles (%0d.%02d us at 50 MHz)",
                     scenario_count, checks, worst_latency,
                     (worst_latency * 20) / 1000, ((worst_latency * 20) % 1000) / 10);
            $finish;
        end else begin
            $fatal(1, "FAIL: %0d of %0d checks failed", failures, checks);
        end
    end

endmodule
